import {routeTextures} from './route-environments.js';
import {shortcutChallenges,shortcutSurface} from './shortcut-terrain.js';
import * as THREE from './vendor/three.module.js';
import {bend,rise,slope} from './track.js';
import {shortcutsFor,shortcutOffset} from './shortcuts.js';
export function createShortcutView(scene,asphalt,renderer){
 const root=new THREE.Group();scene.add(root);const segments=240,positions=new Float32Array((segments+1)*6),uvs=new Float32Array((segments+1)*4),indices=[];
 for(let i=0;i<segments;i++){const k=i*2;indices.push(k,k+1,k+2,k+1,k+3,k+2);}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));geometry.setAttribute('uv',new THREE.BufferAttribute(uvs,2));geometry.setIndex(indices);const material=asphalt.clone();material.color.set('#a4a196');material.roughness=1;material.vertexColors=true;const colors=new Float32Array((segments+1)*6);geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));const road=new THREE.Mesh(geometry,material);road.receiveShadow=true;road.frustumCulled=false;root.add(road);
 const rails=new THREE.InstancedMesh(new THREE.BoxGeometry(.16,.65,1),new THREE.MeshStandardMaterial({color:'#bdc8b0',metalness:.65,roughness:.35,emissive:'#648126',emissiveIntensity:.2}),segments*2);rails.frustumCulled=false;rails.castShadow=true;root.add(rails);const dummy=new THREE.Object3D();
 const stripeGeo=new THREE.BufferGeometry(),stripePositions=new Float32Array(segments*6);stripeGeo.setAttribute('position',new THREE.BufferAttribute(stripePositions,3));const stripe=new THREE.LineSegments(stripeGeo,new THREE.LineBasicMaterial({color:'#cfff71',toneMapped:false}));stripe.frustumCulled=false;root.add(stripe);
 const signCanvas=document.createElement('canvas');signCanvas.width=1024;signCanvas.height=256;const ctx=signCanvas.getContext('2d'),texture=new THREE.CanvasTexture(signCanvas);texture.colorSpace=THREE.SRGBColorSpace;const sign=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,depthWrite:false,toneMapped:false}));sign.scale.set(7.8,1.95,1);root.add(sign);const post=new THREE.Mesh(new THREE.CylinderGeometry(.09,.09,3.6,8),new THREE.MeshStandardMaterial({color:'#8b9f9b',metalness:.5,roughness:.45}));root.add(post);let last='';
 const obstacles=new THREE.Group();root.add(obstacles);let challengeKey='';
 const rampSigns=new THREE.Group();root.add(rampSigns);
 const propMaterials=[new THREE.MeshStandardMaterial({color:'#eb712c',roughness:.8}),new THREE.MeshStandardMaterial({color:'#e7e8d5',roughness:.7}),new THREE.MeshStandardMaterial({color:'#b5aa95',roughness:1}),new THREE.MeshStandardMaterial({color:'#171e24',roughness:.85})];
 const groundTextures=[];let disposed=false;
 routeTextures('rock_face_03',renderer).then(maps=>{if(disposed)return;groundTextures.push(maps.map,maps.normalMap,maps.roughnessMap);propMaterials[2].map=maps.map;propMaterials[2].normalMap=maps.normalMap;propMaterials[2].normalScale.set(.4,.4);propMaterials[2].needsUpdate=true;challengeKey='';}).catch(e=>console.warn('Shortcut texture fallback',e));
 const propMesh=(group,geo,material,x,y,z)=>{const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;group.add(m);return m;};
 const clearProps=()=>{for(const group of [obstacles,rampSigns]){group.traverse(o=>{if(o.isMesh)o.geometry.dispose();});group.clear();}};
 function buildProps(path){clearProps();challengeKey=path.id;const urban=path.profile.startsWith('city-')||!groundTextures.length;material.map=urban?asphalt.map:groundTextures[0];material.normalMap=urban?asphalt.normalMap:groundTextures[1];material.roughnessMap=urban?asphalt.roughnessMap:groundTextures[2];material.normalScale.set(urban?.7:.5,urban?.7:.5);material.color.set(urban?'#b5b2aa':'#dfd7be');material.needsUpdate=true;for(const o of shortcutChallenges(path).obstacles){const group=new THREE.Group();group.userData.challenge=o;obstacles.add(group);if(o.kind==='cone'){for(const dx of [-.2,.2]){propMesh(group,new THREE.BoxGeometry(.38,.07,.38),propMaterials[3],dx,.035,0);propMesh(group,new THREE.ConeGeometry(.17,.65,12),propMaterials[0],dx,.37,0);propMesh(group,new THREE.CylinderGeometry(.085,.115,.13,12),propMaterials[1],dx,.39,0);}}else if(o.kind==='barrier'){propMesh(group,new THREE.BoxGeometry(.95,.55,.3),propMaterials[0],0,.35,0);for(let i=0;i<3;i++){const stripe=propMesh(group,new THREE.BoxGeometry(.15,.56,.315),propMaterials[1],-.32+i*.32,.35,0);stripe.rotation.z=-.3;}for(const x of [-.36,.36])propMesh(group,new THREE.BoxGeometry(.12,.16,.48),propMaterials[3],x,.08,0);}else{const rock=propMesh(group,new THREE.DodecahedronGeometry(.47,1),propMaterials[2],0,.25,0);rock.scale.set(1.25,.65,.85);rock.rotation.set(.3,.6,.2);propMesh(group,new THREE.DodecahedronGeometry(.18,0),propMaterials[2],.38,.12,.22);}}
 for(const r of shortcutChallenges(path).ramps){const g=new THREE.Group();g.userData.crest=r;rampSigns.add(g);for(const x of [-1.9,1.9]){const marker=propMesh(g,new THREE.BoxGeometry(.18,.06,1.3),propMaterials[0],x,0,0);marker.rotation.y=.22*(x>0?-1:1);}}
 }

 return {update(s){const p=s.gameMode==='race'?shortcutsFor(s.trackProfile,s.raceLength||3000).find(p=>p.end>s.distance-35&&p.start<s.distance+380):null;root.visible=!!p&&p.end>s.distance-35&&p.start<s.distance+380;if(!root.visible)return;if(challengeKey!==p.id)buildProps(p);const track=s.trackProfile,d=s.distance,span=p.end-p.start,at=t=>{const a=p.start+span*t,f=a-d;return {a,f,x:shortcutOffset(p,a)+bend(f,d,track),y:rise(f,d,track)+.095};};
  for(let i=0;i<=segments;i++){const q=at(i/segments);for(let side=0;side<2;side++){const k=i*6+side*3;const lateral=side?2.2:-2.2;positions.set([q.x+lateral,q.y+shortcutSurface(p,q.a,lateral),-q.f],k);const rough=q.a>p.entry+12&&q.a<p.exit-12,shade=rough?.64+.13*Math.sin(q.a*.43)*Math.sin(q.a*.77):.96;colors.set([shade,shade*(track.startsWith('city-')?1:.95),shade*(track.startsWith('city-')?1:.82)],k);uvs.set([side*1.45,q.a/3],i*4+side*2);}}
  geometry.attributes.color.needsUpdate=geometry.attributes.position.needsUpdate=geometry.attributes.uv.needsUpdate=true;geometry.computeVertexNormals();
  for(let i=0;i<segments;i++){const a=at(i/segments),b=at((i+1)/segments),mid=(a.a+b.a)/2,open=Math.abs(shortcutOffset(p,mid))<8.8;for(let side=0;side<2;side++){dummy.position.set((a.x+b.x)/2+(side?2.15:-2.15),(a.y+b.y)/2+.36+shortcutSurface(p,mid,side?2.15:-2.15)-(open?20:0),-(a.f+b.f)/2);dummy.rotation.y=-Math.atan(p.chordSlope-slope(d,track));dummy.scale.set(1,open?.001:1,Math.hypot(b.f-a.f,b.x-a.x));dummy.updateMatrix();rails.setMatrixAt(i*2+side,dummy.matrix);}const shown=i%3===0;stripePositions.set([a.x,a.y+.015+shortcutSurface(p,a.a),-a.f,shown?b.x:a.x,shown?b.y+.015+shortcutSurface(p,b.a):a.y+.015+shortcutSurface(p,a.a),shown?-b.f:-a.f],i*6);}
  obstacles.children.forEach(g=>{const o=g.userData.challenge,f=o.distance-d;g.position.set(shortcutOffset(p,o.distance)+bend(f,d,track)+o.x,rise(f,d,track)+.095+shortcutSurface(p,o.distance,o.x),-f);g.rotation.set(0,-Math.atan(p.chordSlope-slope(d,track)),s.shortcutPropHits?.includes(o.id)?1.15:0);g.visible=f>-25&&f<300;});
  rampSigns.children.forEach(g=>{const r=g.userData.crest,f=r.distance-d;g.position.set(shortcutOffset(p,r.distance)+bend(f,d,track),rise(f,d,track)+.13+shortcutSurface(p,r.distance),-f);g.rotation.y=-Math.atan(p.chordSlope-slope(d,track));g.visible=f>-25&&f<300;});
  rails.instanceMatrix.needsUpdate=true;stripeGeo.attributes.position.needsUpdate=true;
  const f=p.entry-d,x=shortcutOffset(p,p.entry)+bend(f,d,track)+p.side*3.4,y=rise(f,d,track);sign.position.set(x,y+4.1,-f);post.position.set(x,y+1.8,-f);sign.visible=post.visible=f>-20&&f<300;
  if(last!==p.id){last=p.id;ctx.fillStyle='#0b1924';ctx.fillRect(0,0,1024,256);ctx.strokeStyle='#d9ff59';ctx.lineWidth=10;ctx.strokeRect(9,9,1006,238);ctx.fillStyle='#d9ff59';ctx.font='bold 78px sans-serif';ctx.textAlign='center';ctx.fillText('SHORTCUT '+(p.side>0?'↗':'↖'),512,112);ctx.font='36px sans-serif';ctx.fillStyle='#b6d9de';ctx.fillText(p.name.toUpperCase()+' · ROUGH / RAMPS',512,192);texture.needsUpdate=true;}
 },dispose(){disposed=true;clearProps();propMaterials.forEach(m=>m.dispose());geometry.dispose();material.dispose();rails.geometry.dispose();rails.material.dispose();stripeGeo.dispose();stripe.material.dispose();texture.dispose();sign.material.dispose();post.geometry.dispose();post.material.dispose();scene.remove(root);}};
}
